def unfold_notes(text):
    notes = []
    for line in text.splitlines():
        if not line.strip():
            continue
        if line[0] in ' \t':
            if not notes:
                raise ValueError('continuation without a note')
            notes[-1] = line.strip()
        else:
            notes.append(line.strip())
    return notes

